// ---------------------------------------------------------------------------
// AUTO-GENERATED by Claude Code
// Purpose: the character picker of tool forms (render._character_picker): a text box you type
//          in to filter a list of icon + name, then pick with a click or the arrow keys + Enter.
// Markup it drives (all rendered by Reflex, found by data- attributes):
//   [data-combo]         the wrapper; gets .is-open while the list shows, .has-value when picked
//   [data-combo-text]    the visible text box (shows the picked label)
//   [data-combo-value]   the hidden input the form submits (the picked value; "" = any)
//   [data-combo-icon]    the picked character's icon
//   [data-combo-list]    the options: buttons with data-value, data-label, data-icon
// One set of listeners on document, so pickers that Reflex mounts later work without setup.
// ---------------------------------------------------------------------------
(() => {
  const parts = (el) => {
    const combo = el.closest("[data-combo]");
    if (!combo) return null;
    return {
      combo,
      text: combo.querySelector("[data-combo-text]"),
      value: combo.querySelector("[data-combo-value]"),
      icon: combo.querySelector("[data-combo-icon]"),
      list: combo.querySelector("[data-combo-list]"),
    };
  };
  const options = (p) => [...p.list.querySelectorAll(".combo-option")];
  const visible = (p) => options(p).filter((option) => !option.hidden);
  const active = (p) => p.list.querySelector(".combo-option.is-active");

  const setActive = (p, option) => {
    options(p).forEach((other) => other.classList.toggle("is-active", other === option));
    if (option) option.scrollIntoView({ block: "nearest" });
  };

  // Show the options matching what is typed (in the label or the id); the first one is active.
  const filter = (p, query) => {
    const wanted = query.trim().toLowerCase();
    options(p).forEach((option) => {
      const hay = (option.dataset.label + " " + option.dataset.value).toLowerCase();
      option.hidden = wanted !== "" && !hay.includes(wanted);
    });
    setActive(p, visible(p)[0] || null);
  };

  // The list is position: fixed, so a scrolling or clipping parent (a result tab, a cell) can't cut it off.
  const place = (p) => {
    const box = p.text.getBoundingClientRect();
    const below = window.innerHeight - box.bottom;
    p.list.style.left = `${box.left}px`;
    p.list.style.minWidth = `${Math.max(box.width, 190)}px`;
    if (below < 220 && box.top > below) {
      p.list.style.top = "";
      p.list.style.bottom = `${window.innerHeight - box.top + 2}px`;
      p.list.style.maxHeight = `${Math.min(300, box.top - 8)}px`;
    } else {
      p.list.style.bottom = "";
      p.list.style.top = `${box.bottom + 2}px`;
      p.list.style.maxHeight = `${Math.min(300, below - 8)}px`;
    }
  };

  const open = (p, showAll) => {
    if (!p.combo.classList.contains("is-open")) delete p.combo.dataset.moved;
    p.combo.classList.add("is-open");
    filter(p, showAll ? "" : p.text.value);
    place(p);
    const picked = options(p).find((option) => option.dataset.value === p.value.value);
    if (showAll && picked) setActive(p, picked);
  };
  const close = (p) => p.combo.classList.remove("is-open");

  const pick = (p, option) => {
    p.value.value = option ? option.dataset.value : "";
    p.text.value = option ? option.dataset.label : "";
    if (option) p.icon.src = option.dataset.icon;
    p.combo.classList.toggle("has-value", Boolean(option));
    close(p);
  };

  // Leaving the box: empty text clears the pick; an exact name picks it; anything else goes
  // back to what was picked, so the text never shows something the form won't send.
  const settle = (p) => {
    const typed = p.text.value.trim().toLowerCase();
    if (typed === "") return pick(p, null);
    const exact = options(p).find((option) => option.dataset.label.toLowerCase() === typed);
    const current = options(p).find((option) => option.dataset.value === p.value.value);
    pick(p, exact || current || null);
  };

  document.addEventListener("focusin", (event) => {
    if (!event.target.matches?.("[data-combo-text]")) return;
    const p = parts(event.target);
    event.target.select();
    open(p, true);
  });

  document.addEventListener("input", (event) => {
    if (!event.target.matches?.("[data-combo-text]")) return;
    open(parts(event.target), false);
  });

  document.addEventListener("focusout", (event) => {
    if (!event.target.matches?.("[data-combo-text]")) return;
    const p = parts(event.target);
    settle(p);
  });

  // mousedown, not click: it comes before the text box loses focus (which would settle and close)
  document.addEventListener("mousedown", (event) => {
    const option = event.target.closest?.(".combo-option");
    if (!option) return;
    event.preventDefault();
    const p = parts(option);
    pick(p, option);
    p.text.blur();
  });

  document.addEventListener(
    "keydown",
    (event) => {
      if (!event.target.matches?.("[data-combo-text]")) return;
      const p = parts(event.target);
      const isOpen = p.combo.classList.contains("is-open");
      if (event.key === "ArrowDown" || event.key === "ArrowUp") {
        event.preventDefault();
        if (!isOpen) return open(p, true);
        const shown = visible(p);
        const at = shown.indexOf(active(p));
        const next = event.key === "ArrowDown" ? Math.min(at + 1, shown.length - 1) : Math.max(at - 1, 0);
        setActive(p, shown[next] || null);
        p.combo.dataset.moved = "1";
      } else if (event.key === "Enter" && isOpen) {
        // the first Enter picks; the form only runs on an Enter with the list closed
        event.preventDefault();
        // nothing typed and no arrow key used: Enter means "any", not the first of the list
        const chose = p.text.value.trim() !== "" || p.combo.dataset.moved === "1";
        pick(p, chose ? active(p) : null);
      } else if (event.key === "Escape" && isOpen) {
        // capture phase + stop: Esc closes this list, not the floating view around it (panes.js)
        event.preventDefault();
        event.stopPropagation();
        settle(p);
      }
    },
    true,
  );

  // a list left open is in the wrong place once the page scrolls or resizes: close it
  const closeAll = (event) => {
    if (event?.target?.closest?.("[data-combo-list]")) return;  // scrolling the list itself
    document.querySelectorAll("[data-combo].is-open").forEach((combo) => combo.classList.remove("is-open"));
  };
  window.addEventListener("scroll", closeAll, true);
  window.addEventListener("resize", closeAll);
})();
